export function MinMaxWidth({
  requested = {{requested}},
  min = {{min}},
  max = {{max}},
  background = "{{background}}",
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 340 }}
      role="img" aria-label="A box asking for one width but clamped by min-width and max-width; the rendered width is never outside that range">
      <div style={{ background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 12, boxSizing: "border-box" }}>
        <div style={{ width: requested, minWidth: min, maxWidth: max, background, borderRadius: 6, padding: 14, fontWeight: 700, textAlign: "center", boxSizing: "border-box" }}>
          box
        </div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        requested {requested}px &middot; min-width {min}px &middot; max-width {max}px &mdash; the browser clamps automatically
      </p>
    </div>
  );
}
